import hashlib, json, re
from pathlib import Path

folder = Path('products/services/catalogue-inbound-cad')
source = folder / 'decision-table-rehearsal.json'
raw = source.read_bytes()
packet = json.loads(raw)
drafts = packet.get('operator_reply_drafts', {})
checks = packet.get('checks', [])
expected_routes = {'FOLLOW_AUTHORIZED_DIAGNOSTIC_WORKFLOW', 'NONBINDING_COMMISSION_CLARIFICATION', 'HAND_OFF_TO_AUTHORIZED_OPERATOR', 'CLARIFY_SCOPE'}
results = {'five_fictional_routes_passed': len(checks) == 5 and all(row.get('passed') is True and row.get('expected') == row.get('actual') for row in checks) and expected_routes == {row.get('actual') for row in checks}}
for branch in ('diagnostic', 'commission'):
    draft = drafts.get(branch)
    if not isinstance(draft, str):
        results[branch] = {'usable_text': False, 'observed_type': type(draft).__name__}
        continue
    parts = re.split(r'(?m)^FR\s*$', draft, maxsplit=1)
    english, french = (parts + [''])[:2]
    results[branch] = {'english_and_french': len(parts) == 2 and bool(re.search(r'(?m)^EN\s*$', english)) and bool(french.strip()), 'english_ai_disclosure': 'autonomous ai' in english.casefold(), 'french_ai_disclosure': ('ia autonome' in french.casefold() or 'agents autonomes' in french.casefold()), 'sha256': hashlib.sha256(draft.encode()).hexdigest()}
    if branch == 'commission':
        results[branch]['operator_and_buyer_confirmation_language'] = all(term in english.casefold() for term in ('authorized operator', 'approve', 'your confirmation', 'exact terms'))
    else:
        results[branch]['scope_and_manual_location_language'] = all(term in english.casefold() for term in ('20 rows', 'synthetic or anonymized', 'attachments', 'style', 'manual'))
report = {'source': str(source), 'source_sha256': hashlib.sha256(raw).hexdigest(), 'draft_keys': sorted(drafts), 'checks': results, 'coverage': 'Committed fictional routing and draft text only. No delivery, accepted order, deposit attestation or Treasury posting checked.'}
report['all_pass'] = results['five_fictional_routes_passed'] and all(all(value is True for key, value in results[branch].items() if key not in ('sha256', 'observed_type')) for branch in ('diagnostic', 'commission'))
output = json.dumps(report, ensure_ascii=False, indent=2)
(folder / 'reply-readback-verification.json').write_text(output + '\n', encoding='utf-8')
print(output)
